9a6ee59421 (Miloš Komarčević 2022-10-18 15:50:01 +0200 198)   const byte* next_in = compressedBuf;
9a6ee59421 (Miloš Komarčević 2022-10-18 15:50:01 +0200 199)   size_t available_out;
9a6ee59421 (Miloš Komarčević 2022-10-18 15:50:01 +0200 200)   byte* next_out;
9a6ee59421 (Miloš Komarčević 2022-10-18 15:50:01 +0200 201)   size_t total_out = 0;
