9a6ee59421 (Miloš Komarčević 2022-10-18 15:50:01 +0200 205)     available_out = uncompressedLen - total_out;
9a6ee59421 (Miloš Komarčević 2022-10-18 15:50:01 +0200 206)     next_out = arr.data() + total_out;
